L000294	\section{Gaussian statistics: Two-port homodyne detection} \label{Appendix A}
L000295	  \setcounter{equation}{0}
L000296	In this section, we derive the Gaussian probability distribution~\eqref{eq:Gaussian_pdf_main} for two-port homodyne detection at the output of a two-channel unitary $\mathrm{U}(2)$ network probed by a TMSS,
L000297	\begin{equation}
L000298	\ket{\psi_{\mathrm{in}}}
L000299	= \hat{D}_1(\alpha_1)\,\hat{D}_2(\alpha_2)\,\hat{S}_{12}(\xi)\,\ket{0,0},
L000300	\label{SM:INPUTstate}
L000301	\end{equation}
L000302	where $\hat{D}_i(\alpha_i)$ is the single-mode displacement operator acting on mode $i$ with
L000303	$\alpha_i = |\alpha_i|e^{i\beta_i}$ for $i = 1,2$, and $\hat{S}_{12}(\xi)$ is the two-mode squeezing operator with complex squeezing parameter $\xi = r e^{i\theta}$. For simplicity, and without loss of optimality for the quantum Fisher information matrix, we restrict to equal real displacements in both input modes,
L000304	\(|\alpha_1| = |\alpha_2| = |\alpha|\) and \(\beta_1 = \beta_2 = 0\), and to real squeezing, $\xi = r$ with $\theta = 0$, which satisfies the optimality condition $\theta - \beta_1 - \beta_2 = 0$~\cite{537s-r3t8}.
L000305	
L000306	Adopting the quadrature ordering
L000307	\(\mathbf{z} = (x_1,\,p_1,\,x_2,\,p_2)^{\mathsf T}\),
L000308	the initial displacement vector of the input state~\eqref{SM:INPUTstate} is $\bm d_0=\sqrt{2}\,|\alpha|(1,0,1,0)^\mathsf{T},$ and the covariance matrix of the two-mode squeezed vacuum $\hat{S}_{12}(r)\ket{0,0}$ is
L000309	\begin{equation}
L000310	\Gamma_0
L000311	=
L000312	\frac{1}{2}\begin{pmatrix}
L000313	\cosh(2r) & 0 & \sinh(2r) & 0 \\
L000314	0 & \cosh(2r) & 0 & -\sinh(2r) \\
L000315	\sinh(2r) & 0 & \cosh(2r) & 0 \\
L000316	0 & -\sinh(2r) & 0 & \cosh(2r)
L000317	\end{pmatrix}.
L000318	\end{equation}
L000319	After the action of the two-channel network $U_{\bm{\phi}}$, the displacement and covariance matrix transform as
L000320	\begin{equation}
L000321	 \bm d_{\bm{\phi}} = R_{\bm{\phi}}\,\bm{d_0},
L000322	\qquad
L000323	 \Gamma_{\bm{\phi}} = R_{\bm{\phi}}\,\Gamma_0\,R_{\bm{\phi}}^{\mathsf T},
L000324	\end{equation}
L000325	where $R_{\bm{\phi}}$ is the real orthogonal symplectic matrix associated with the unitary $U_{\bm{\phi}}$,
L000326	\begin{equation}
L000327	    R_{\bm{\phi}} =
L000328	    \begin{pmatrix}
L000329	        \Re[U_{\bm{\phi}}] & -\Im[U_{\bm{\phi}}] \\
L000330	        \Im[U_{\bm{\phi}}] & \Re[U_{\bm{\phi}}]
L000331	    \end{pmatrix}.
L000332	 \label{App:R}
L000333	\end{equation}
L000334	
L000335	We then perform homodyne measurements on both output ports of the network. On mode \(j = 1,2\) we measure the quadrature $\hat x_{\theta_j}^{(j)}=\frac{1}{\sqrt{2}}\bigl(e^{-i\theta_j}\hat a_{j,\text{out}} + e^{i\theta_j}\hat a_{j,\text{out}}^\dagger\bigr)$, rotated by the LO phase \(\theta_j\). Collecting the two measurement outcomes into the vector \(\bm{x} = (x_1, x_2)^\mathsf T\), where $x_j$ is the eigenvalue of $\hat x^{(j)}_{\theta_j}$, the measured observables can be written as linear combinations of the output quadratures,
L000336	\begin{equation}
L000337	    \hat{\bm{x}} = M_{\hom} \,\hat{\mathbf{z}}_{\bm{\phi}},
L000338	\end{equation}
L000339	where \(\hat{\mathbf{z}}_{\bm{\phi}}\) is the output quadrature operator vector and the \(2\times 4\) matrix $M_{\hom}$ selects the rotated quadratures measured by balanced homodyne detection:
L000340	\begin{equation}
L000341	    M_{\hom}
L000342	    =
L000343	    \begin{pmatrix}
L000344	        \cos(\theta_1) & \sin(\theta_1) & 0 & 0 \\
L000345	        0 & 0 & \cos(\theta_2) & \sin(\theta_2)
L000346	    \end{pmatrix}.
L000347	\end{equation}
L000348	
L000349	Since the input state is Gaussian and the transformation $U_{\bm{\phi}}$ is linear and passive, the joint statistics of $(x_1,x_2)$ remain Gaussian. The corresponding mean vector and covariance matrix are
L000350	   $\bm{\mu}_{\bm{\phi}} = M_{\hom}\,\bm d_{\bm{\phi}}$ and $\Sigma_{\bm{\phi}}
L000351	    =
L000352	    M_{\hom}\,\Gamma_{\bm{\phi}}\,M_{\hom}^{\mathsf T}$, respectively. The joint probability density of observing outcomes \(\bm{x} = (x_1,x_2)^\mathsf T\) is therefore
