L000573	\begin{equation}
L000574	    \mathcal{F}
L000575	=
L000576	  \frac{\beta^{2}}{\Lambda^{2}}\,
L000577	  \begin{pmatrix}
L000578	    D_{1} & 0   & A   & B   \\
L000579	    0     & 0   & 0   & 0   \\
L000580	    A     & 0   & D_{3} & C \\
L000581	    B     & 0   & C   & D_{4}
L000582	  \end{pmatrix}
L000583	    \;+\;
L000584	\frac{2(1-\beta)\beta}{\Lambda}
L000585	    \begin{pmatrix}
L000586	        0 & 0 & 0 & 0 \\
