L000588	        0 & 0 & 0 & 0 \\
L000589	        0 & 0 & 0 & 0
L000590	    \end{pmatrix}.
L000591	    \label{eq:F2_def}
L000592	\end{equation}
L000593	Equation~\eqref{eq:F2_def} shows how the
L000594	Heisenberg scaling of the total Fisher information depends on the allocation of photons between squeezing and displacement through
L000595	\(N_{\mathrm{s}}\) and \(N_{\mathrm{c}}\). The multiparameter Cram\'{e}r–Rao bound for any unbiased estimator
L000596	\(\widetilde{\bm{\phi}}\) is given by $ \mathrm{Cov}\bigl[\widetilde{\bm{\phi}}\bigr]
L000597	    \geq
L000598	F^{-1}/M$.
L000599	Therefore, using Eq.~\eqref{eq:FtotAsym}, the marginal variances of the four parameters $\phi_0,\phi_1,\phi_2,\phi_3$ satisfy, at leading order,
L000600	\begin{align}
L000601	    \Delta^2 \widetilde{\phi}_0
L000602	    &\;\ge\;
L000603	    \frac{1}{M\,N^2}\,\bigl[\mathcal{F}^{-1}\bigr]_{11}+O\bigg(\frac{1}{MN^3}\bigg),\label{Appeq:CRB_diagonal_phi0}\\
L000604	    \Delta^2 \widetilde{\phi}_1
L000605	    &\;\ge\;
L000606	      \frac{1}{M\,N^2}\,\bigl[\mathcal{F}^{-1}\bigr]_{22}+O\bigg(\frac{1}{MN^3}\bigg),\label{Appeq:CRB_diagonal_phi}\\
L000607	    \Delta^2 \widetilde{\phi}_2
L000608	    &\;\ge\;
L000609	      \frac{1}{M\,N^2}\,\bigl[\mathcal{F}^{-1}\bigr]_{33}+O\bigg(\frac{1}{MN^3}\bigg),\label{Appeq:CRB_diagonal_psi}\\
L000610	    \Delta^2 \widetilde{\phi}_3
L000611	    &\;\ge\;
L000612	     \frac{1}{M\,N^2}\,\bigl[\mathcal{F}^{-1}\bigr]_{44}+O\bigg(\frac{1}{MN^3}\bigg),
L000613	\label{Appeq:CRB_diagonal_omega}
L000614	\end{align}
L000615	as in Eqs.~\eqref{eq:CRB_phi0}--\eqref{eq:CRB_omega} of the main text. Equations~\eqref{Appeq:CRB_diagonal_phi0}–\eqref{Appeq:CRB_diagonal_omega} make explicit that all four parameters exhibit Heisenberg scaling
L000616	\(\Delta^2 \widetilde{\phi}_i \propto 1/N^2\), with prefactors determined by the diagonal elements of the coefficient matrix \(\mathcal{F}^{-1}\) (see Fig.~\ref{fig:Eff_FIM_diagonal}).
L000617	Since $\mathcal{F}$ is block diagonal, its determinant factorizes as
L000618	\begin{equation}
L000619	\det (\mathcal{F})
L000620	=
L000621	\left(\frac{2(1-\beta)\beta}{\Lambda}D_2\right)
L000622	\det\!\left(\frac{\beta^{2}}{\Lambda^{2}}
L000623	\begin{pmatrix}
L000624	D_{1} & A & B\\
L000625	A & D_{3} & C\\
L000626	B & C & D_{4}
L000627	\end{pmatrix}\right),
