L000630	\begin{equation}
L000631	\det
L000632	\begin{pmatrix}
L000633	D_{1} & A & B\\
L000634	A & D_{3} & C\\
L000635	B & C & D_{4}
L000636	\end{pmatrix}=
L000637	16384\,(k_1+k_2)^2\,(k_1k_2-k_3^2)^2\,\Lambda^3,
