L000732	\left[
L000733	\left(\Sigma_{\boldsymbol{\phi}}^{\eta}\right)^{-1}
L000734	\left(\partial_i\Sigma_{\boldsymbol{\phi}}\right)
L000735	\left(\Sigma_{\boldsymbol{\phi}}^{\eta}\right)^{-1}
L000736	\left(\partial_j\Sigma_{\boldsymbol{\phi}}\right)
